    private readonly Random _random = new();
    private CancellationTokenSource? _pollingCts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling for the given warehouse. Reference-counted so multiple
    /// components can request polling — it only actually starts once.
    /// </summary>
    public void StartPolling(string warehouseId, Func<Action, Task> invokeAsync)
    {
        _subscriberCount++;
        if (_subscriberCount > 1)
            return;

        _pollingCts = new CancellationTokenSource();
        var token = _pollingCts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(10), token);
                    var count = await GetLowStockCountAsync(warehouseId);
                    CurrentAlertCount = count;

                    // Marshal the notification back onto the Blazor sync context
                    await invokeAsync(() => OnChange?.Invoke());
                }
                catch (OperationCanceledException)
                {
                    break;
                }
            }
        }, token);
    }

    /// <summary>
    /// Decrements the subscriber count; stops the polling loop when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollingCts?.Cancel();
            _pollingCts?.Dispose();
            _pollingCts = null;
        }
    }

    /// <summary>
    /// Forces an immediate refresh (e.g., after a warehouse switch).
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _pollingCts?.Cancel();
        _pollingCts?.Dispose();
    }
}

