@using sv_6c4d7a06ef5b4a1ba56394911c901b10.Services
@inject CascadingValueSource<WarehouseState> WarehouseSource
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: 200px;"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private string _selectedId = "WH-001";

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
            _selectedId = Warehouse.WarehouseId;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString() ?? "WH-001";
        var name = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? "Unknown";

        var newState = new WarehouseState { WarehouseId = id, WarehouseName = name };
        await WarehouseSource.NotifyChangedAsync(newState);
    }
}

