@page "/dashboard"
@using sv_6c4d7a06ef5b4a1ba56394911c901b10.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Current Warehouse: @(Warehouse?.WarehouseName ?? "Loading...")
        </h5>
        <p class="card-text">Warehouse ID: @(Warehouse?.WarehouseId ?? "—")</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body d-flex align-items-center gap-3">
        <h5 class="card-title mb-0">Low-Stock Alerts</h5>
        <span class="badge bg-danger rounded-pill fs-5">@AlertService.CurrentAlertCount</span>
        <span class="text-muted small">Refreshes every 10 seconds</span>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private string _currentWarehouseId = string.Empty;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        var whId = Warehouse?.WarehouseId ?? "WH-001";

        if (whId != _currentWarehouseId)
        {
            // Warehouse changed — restart polling for the new warehouse
            if (!string.IsNullOrEmpty(_currentWarehouseId))
                AlertService.StopPolling();

            _currentWarehouseId = whId;
            await AlertService.RefreshAsync(whId);
            AlertService.StartPolling(whId, InvokeAsync);
        }
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnChange -= _handler;

        AlertService.StopPolling();
    }
}

