using sv_6c4d7a06ef5b4a1ba56394911c901b10.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Warehouse selection — CascadingValueSource crosses render mode boundaries,
// so the static MainLayout's interactive WarehouseSelector can push updates
// to all [CascadingParameter] subscribers in interactive pages.
builder.Services.AddCascadingValue(sp =>
{
    var initial = new WarehouseState();
    return new CascadingValueSource<WarehouseState>(initial, isFixed: false);
});

// Scoped so each circuit (user) gets its own alert state and polling loop.
builder.Services.AddScoped<InventoryAlertService>();

